matchEach('A')
  .with('A', () => { sideEffects.push('A'); return 1; })
  .with('B', () => { sideEffects.push('B'); return 2; });
// no .run()
expect(sideEffects).toEqual([]);  // deferred
// or expect(sideEffects).toEqual(['A']);  // eager
