{"content": "import { Pattern } from './types/Pattern';
import { MatchEach } from './types/MatchEach';
import * as symbols from './internals/symbols';
import { matchPattern } from './internals/helpers';
import { NonExhaustiveError } from './errors';

type WithClause<output> = {
  kind: 'with';
  patterns: Pattern<unknown>[];
  predicate: ((value: unknown) => unknown) | undefined;
  handler: (selections: unknown, value: unknown) => output;
};

type WhenClause<output> = {
  kind: 'when';
  predicate: (value: unknown) => unknown;
  handler: (value: unknown) => output;
};

type TapClause<output> = {
  kind: 'tap';
  callback: (value: output) => void;
};

type Clause<output> = WithClause<output> | WhenClause<output> | TapClause<output>;

/**
 * `matchEach` creates a **multi-pattern matching expression**.
 *
 * Unlike `match`, which short-circuits on the first matching pattern,
 * `matchEach` evaluates **all** registered patterns against the input and
 * collects the result of every matching handler into an array, returned
 * in the order the clauses were declared.
 *
 *  * Use `.with(pattern, handler)` to pattern match on the input.
 *  * Use `.exhaustive()`, `.otherwise(() => defaultValue)` or the unsafe
 *    `.run()` method to evaluate the expression and get the array of
 *    results of all the matching handlers.
 *
 * `matchEach` can also be called without a value argument, using explicit
 * type parameters, to build a reusable compiled matcher with
 * `.toFunction()`, `.toExhaustiveFunction()` or `.toPartialFunction()`.
 *
 * @example
 *  declare let input: "A" | "B";
 *
 *  return matchEach(input)
 *    .with("A", () => "It's an A!")
 *    .with("B", () => "It's a B!")
 *    .exhaustive();
 *
 */
export function matchEach<const input, output = symbols.unset>(
  value: input
): MatchEach<input, output>;
export function matchEach<const input, output = symbols.unset>(): MatchEach<
  input,
  output
>;
export function matchEach(...args: unknown[]) {
  return new MatchEachExpression(
    args.length > 0 ? (args[0] as any) : UNSET_INPUT
  ) as any;
}

const UNSET_INPUT = Symbol('ts-pattern/match-each/unset-input');

/**
 * This class represents a matchEach expression. It follows the
 * builder pattern, we chain methods to add clauses to the expression
 * until we call `.exhaustive`, `.otherwise`, the unsafe `.run`
 * method, or compile the expression with `.toFunction()`,
 * `.toExhaustiveFunction()` or `.toPartialFunction()`.
 *
 * The types of this class aren't public, the public type definition
 * can be found in src/types/MatchEach.ts.
 *
 * Clauses are only evaluated when the expression is run, so the same
 * builder can be reused to compile a function that will match on
 * different inputs later on.
 */
class MatchEachExpression<output> {
  constructor(
    private input: unknown,
    private clauses: Clause<output>[] = []
  ) {}

  with(...args: any[]): MatchEachExpression<output> {
    const handler: (selections: unknown, value: unknown) => output =
      args[args.length - 1];

    const patterns: Pattern<unknown>[] = [args[0]];
    let predicate: ((value: unknown) => unknown) | undefined = undefined;

    if (args.length === 3 && typeof args[1] === 'function') {
      // case with guard as second argument
      predicate = args[1];
    } else if (args.length > 2) {
      // case with several patterns
      patterns.push(...args.slice(1, args.length - 1));
    }

    return new MatchEachExpression<output>(this.input, [
      ...this.clauses,
      { kind: 'with', patterns, predicate, handler },
    ]);
  }

  when(
    predicate: (value: unknown) => unknown,
    handler: (value: unknown) => output
  ): MatchEachExpression<output> {
    return new MatchEachExpression<output>(this.input, [
      ...this.clauses,
      { kind: 'when', predicate, handler },
    ]);
  }

  tap(callback: (value: output) => void): MatchEachExpression<output> {
    return new MatchEachExpression<output>(this.input, [
      ...this.clauses,
      { kind: 'tap', callback },
    ]);
  }

  otherwise(handler: (value: unknown) => output): output[] {
    const value = this.requireInput();
    const results = this.evaluate(value);
    if (results.length > 0) return results;
    return [handler(value)];
  }

  exhaustive(unexpectedValueHandler = defaultCatcher): output[] {
    const value = this.requireInput();
    const results = this.evaluate(value);
    if (results.length > 0) return results;
    return [unexpectedValueHandler(value)];
  }

  run(): output[] {
    return this.exhaustive();
  }

  returnType(): MatchEachExpression<output> {
    return this;
  }

  narrow(): MatchEachExpression<output> {
    return this;
  }

  toFunction(): (input: unknown) => output[] {
    return (value: unknown) => {
      const results = this.evaluate(value);
      if (results.length === 0) throw new NonExhaustiveError(value);
      return results;
    };
  }

  toExhaustiveFunction(): (input: unknown) => output[] {
    return this.toFunction();
  }

  toPartialFunction(): (input: unknown) => output[] | undefined {
    return (value: unknown) => {
      const results = this.evaluate(value);
      return results.length > 0 ? results : undefined;
    };
  }

  private requireInput(): unknown {
    if (this.input === UNSET_INPUT) {
      throw new Error(
        `matchEach was called without a value. ` +
          `Pass a value to matchEach(...), or use .toFunction(), ` +
          `.toExhaustiveFunction() or .toPartialFunction() to compile ` +
          `the clauses into a reusable function.`
      );
    }
    return this.input;
  }

  private evaluate(value: unknown): output[] {
    const results: output[] = [];

    for (const clause of this.clauses) {
      switch (clause.kind) {
        case 'with': {
          let hasSelections = false;
          let selected: Record<string, unknown> = {};
          const select = (key: string, value: unknown) => {
            hasSelections = true;
            selected[key] = value;
          };

          const matched =
            clause.patterns.some((pattern) =>
              matchPattern(pattern, value, select)
            ) && (clause.predicate ? Boolean(clause.predicate(value)) : true);

          if (matched) {
            const selections = hasSelections
              ? symbols.anonymousSelectKey in selected
                ? selected[symbols.anonymousSelectKey]
                : selected
              : value;
            results.push(clause.handler(selections, value));
          }
          break;
        }
        case 'when': {
          if (Boolean(clause.predicate(value))) {
            results.push(clause.handler(value));
          }
          break;
        }
        case 'tap': {
          for (const result of results) {
            clause.callback(result);
          }
          break;
        }
      }
    }

    return results;
  }
}

function defaultCatcher(input: unknown): never {
  throw new NonExhaustiveError(input);
}
