{"content": "import { matchEach, P, NonExhaustiveError } from '../src';
import { Equal, Expect } from '../src/types/helpers';
import { Option } from './types-catalog/utils';

type Country = 'France' | 'Germany' | 'Spain' | 'USA';

describe('matchEach', () => {
  it('should collect the results of all matching handlers in declaration order', () => {
    const result = matchEach(2)
      .with(P.even, (n) => `even: ${n}`)
      .with(P.gt(1), (n) => `greater than 1: ${n}`)
      .with(P.lt(3), (n) => `less than 3: ${n}`)
      .with(P.gt(100), () => 'too big')
      .run();

    expect(result).toStrictEqual([
      'even: 2',
      'greater than 1: 2',
      'less than 3: 2',
    ]);
  });

  it('should return an empty array when nothing matches (with .otherwise)', () => {
    const result = matchEach(1000)
      .with(P.lt(3), () => 'small')
      .otherwise(() => 'default');

    expect(result).toStrictEqual(['default']);
  });

  it("should evaluate every branch, not stop at the first match (unlike match)", () => {
    const result = matchEach<'a' | 'b' | 'c'>('a')
      .with('a', () => 'first')
      .with('b', () => 'second')
      .with('c', () => 'third')
      .exhaustive();

    expect(result).toStrictEqual(['first']);

    const result2 = matchEach('a' as string)
      .with('a', () => 'A')
      .with('a', () => 'A again')
      .otherwise(() => 'never');

    expect(result2).toStrictEqual(['A', 'A again']);
  });

  it('should typecheck the same handlers as match (selections and value)', () => {
    matchEach<Option<number>>({ kind: 'some', value: 2 })
      .with({ kind: 'some', value: P.select() }, (x) => {
        type t = Expect<Equal<typeof x, number>>;
        return 'selected';
      })
      .with({ kind: 'some' }, ({ value }) => {
        type t = Expect<Equal<typeof value, number>>;
        return 'some';
      })
      .with({ kind: 'none' }, () => 'none')
      .exhaustive();
  });

  it('should support multiple patterns in a single .with()', () => {
    const f = (input: Country) =>
      matchEach(input)
        .with('France', 'Germany', () => 'Europe')
        .with('Spain', 'USA', () => 'not Europe')
        .run();

    expect(f('France')).toStrictEqual(['Europe']);
    expect(f('Germany')).toStrictEqual(['Europe']);
    expect(f('Spain')).toStrictEqual(['not Europe']);
    expect(f('USA')).toStrictEqual(['not Europe']);
  });

  it('should support several patterns and a guard predicate in .with()', () => {
    const f = (input: number) =>
      matchEach(input)
        .with(P.number, (n) => n > 0, (n) => {
          type t = Expect<Equal<typeof n, number>>;
          return `positive: ${n}`;
        })
        .when((n) => n < 0, (n) => `negative: ${n}`)
        .otherwise(() => 'zero');

    expect(f(2)).toStrictEqual(['positive: 2']);
    expect(f(-2)).toStrictEqual(['negative: -2']);
    expect(f(0)).toStrictEqual(['zero']);
  });

  it('should support .when()', () => {
    const f = (input: number) =>
      matchEach(input)
        .when(P.even, (n) => `even: ${n}`)
        .when(P.lt(5), (n) => `small: ${n}`)
        .otherwise(() => 'big odd');

    expect(f(2)).toStrictEqual(['even: 2', 'small: 2']);
    expect(f(4)).toStrictEqual(['even: 4', 'small: 4']);
    expect(f(3)).toStrictEqual(['small: 3']);
    expect(f(7)).toStrictEqual(['big odd']);
  });

  it('should support .returnType()', () => {
    const f = (input: number) =>
      matchEach(input)
        .returnType<string>()
        .with(P.even, (n) => `even: ${n}`)
        .with(P.odd, (n) => `odd: ${n}`)
        .exhaustive();

    type t = Expect<Equal<ReturnType<typeof f>, string[]>>;
    expect(f(2)).toStrictEqual(['even: 2']);
  });

  it('should support .narrow()', () => {
    const f = (input: { prop?: string }) =>
      matchEach(input)
        .with({ prop: P.nullish.optional() }, () => false)
        .narrow()
        .otherwise(({ prop }) => {
          type t = Expect<Equal<typeof prop, string>>;
          return true;
        });

    expect(f({})).toStrictEqual([false]);
    expect(f({ prop: 'hello' })).toStrictEqual([true]);
  });

  it('should allow patterns against the original input type in subsequent .with() calls', () => {
    // In `match`, the second `.with('a')` would be a type error because
    // 'a' was already excluded from the input type. In `matchEach` it is
    // allowed, since all branches are always evaluated.
    const f = (input: 'a' | 'b') =>
      matchEach(input)
        .with('a', () => 'a first')
        .with('a', () => 'a second')
        .with('b', () => 'b')
        .exhaustive();

    expect(f('a')).toStrictEqual(['a first', 'a second']);
    expect(f('b')).toStrictEqual(['b']);
  });

  describe('.run()', () => {
    it('should throw NonExhaustiveError if nothing matched', () => {
      expect(() =>
        matchEach(1000)
          .with(P.lt(3), (n) => n)
          .run()
      ).toThrow(NonExhaustiveError);
    });
  });

  describe('.exhaustive()', () => {
    it('should throw NonExhaustiveError if nothing matched', () => {
      const input = 'spain' as Country;
      expect(() =>
        matchEach(input)
          .with('France', () => 'x')
          .with('Germany', () => 'x')
          .with('Spain', () => 'x')
          .with('USA', () => 'x')
          .exhaustive()
      ).toThrow(NonExhaustiveError);
    });

    it('should be a type error if not all input cases are handled', () => {
      const input = 'France' as Country;
      matchEach(input)
        .with('France', () => 'x')
        .with('Germany', () => 'x')
        // @ts-expect-error: 'Spain' and 'USA' are missing
        .exhaustive();
    });

    it('should call the fallback handler if no pattern matched at runtime', () => {
      const input: 'a' | 'b' = 'c' as any;
      const result = matchEach(input)
        .with('a', (x) => x)
        .with('b', (x) => x)
        .exhaustive((v) => ({ unexpectedValue: v }));

      type t = Expect<
        Equal<typeof result, { unexpectedValue: unknown } | 'a' | 'b'[]>
      >;

      expect(result).toStrictEqual([{ unexpectedValue: 'c' }]);
    });
  });

  describe('.otherwise()', () => {
    it('should return the results of matching patterns if any matched', () => {
      const result = matchEach(2)
        .with(P.even, (n) => `even: ${n}`)
        .with(P.lt(3), (n) => `small: ${n}`)
        .otherwise(() => 'default');

      expect(result).toStrictEqual(['even: 2', 'small: 2']);
    });

    it('should return [handler(value)] if nothing matched', () => {
      const result = matchEach(1000)
        .with(P.lt(3), (n) => `small: ${n}`)
        .otherwise((n) => `default: ${n}`);

      expect(result).toStrictEqual(['default: 1000']);
    });

    it('should never throw', () => {
      expect(
        matchEach('x' as 'a' | 'b')
          .with('a', () => 'a')
          .otherwise((v) => `fallback: ${v}`)
      ).toStrictEqual(['fallback: x']);
    });
  });

  describe('.tap()', () => {
    it('should call the callback once per result collected up to the tap point', () => {
      const calls: string[] = [];

      matchEach(2)
        .with(P.even, (n) => `even: ${n}`)
        .with(P.lt(3), (n) => `small: ${n}`)
        .tap((r) => calls.push(r))
        .with(P.gt(1), (n) => `big: ${n}`)
        .run();

      // only the results collected before the tap point
      expect(calls).toStrictEqual(['even: 2', 'small: 2']);
    });

    it('should see all results collected up to its position, in declaration order', () => {
      const calls: string[] = [];

      matchEach(2)
        .with(P.even, (n) => `even: ${n}`)
        .with(P.lt(3), (n) => `small: ${n}`)
        .tap((r) => calls.push(`first: ${r}`))
        .with(P.gt(1), (n) => `big: ${n}`)
        .tap((r) => calls.push(`second: ${r}`))
        .run();

      expect(calls).toStrictEqual([
        'first: even: 2',
        'first: small: 2',
        'second: even: 2',
        'second: small: 2',
        'second: big: 2',
      ]);
    });

    it('should not affect the results array', () => {
      const result = matchEach(2)
        .with(P.even, (n) => `even: ${n}`)
        .tap(() => {
          throw new Error('nope');
        })
        .with(P.lt(3), (n) => `small: ${n}`)
        .run();

      expect(result).toStrictEqual(['even: 2', 'small: 2']);
    });

    it('should also be executed inside compiled functions', () => {
      const calls: number[] = [];

      const fn = matchEach<number>()
        .with(P.even, (n) => n * 2)
        .tap((r) => calls.push(r))
        .toFunction();

      expect(fn(4)).toStrictEqual([8]);
      expect(calls).toStrictEqual([8]);

      expect(fn(3)).toStrictEqual([] === undefined ? [] : []);
    });
  });

  describe('compiled functions', () => {
    it('.toFunction() should compile the clauses into a reusable function', () => {
      const isEven = matchEach<number>()
        .with(P.even, (n) => `even: ${n}`)
        .with(P.odd, (n) => `odd: ${n}`)
        .toFunction();

      expect(isEven(2)).toStrictEqual(['even: 2']);
      expect(isEven(3)).toStrictEqual(['odd: 3']);
      type t = Expect<Equal<ReturnType<typeof isEven>, string[]>>;
    });

    it('.toFunction() should throw NonExhaustiveError if no pattern matches', () => {
      const f = matchEach<string>()
        .with('a', () => 'A')
        .toFunction();

      expect(() => f('b')).toThrow(NonExhaustiveError);
    });

    it('.toExhaustiveFunction() should compile the clauses into a reusable function', () => {
      const f = matchEach<Country>()
        .with('France', 'Germany', 'Spain', 'USA', (c) => `country: ${c}`)
        .toExhaustiveFunction();

      expect(f('France')).toStrictEqual(['country: France']);
      type t = Expect<Equal<ReturnType<typeof f>, string[]>>;
    });

    it('.toExhaustiveFunction() should be a type error if not exhaustive', () => {
      matchEach<Country>()
        .with('France', () => 'x')
        .with('Germany', () => 'x')
        // @ts-expect-error: 'Spain' and 'USA' are missing
        .toExhaustiveFunction();
    });

    it('.toPartialFunction() should compile into a partial function', () => {
      const f = matchEach<Country>()
        .with('France', (c) => `country: ${c}`)
        .toPartialFunction();

      expect(f('France')).toStrictEqual(['country: France']);
      expect(f('Germany')).toBeUndefined();
      type t = Expect<Equal<ReturnType<typeof f>, string[] | undefined>>;
    });

    it('.toPartialFunction() should never throw', () => {
      const f = matchEach<string>()
        .with('a', () => 'A')
        .toPartialFunction();

      expect(f('b')).toBeUndefined();
    });

    it('compiled functions should keep producing independent selection results across calls', () => {
      const f = matchEach<Option<number>>()
        .with(
          { kind: 'some', value: P.select() },
          (value) => `selected: ${value}`
        )
        .toFunction();

      expect(f({ kind: 'some', value: 1 })).toStrictEqual(['selected: 1']);
      expect(f({ kind: 'some', value: 2 })).toStrictEqual(['selected: 2']);
      expect(f({ kind: 'none' })).toStrictEqual([]);
    });
  });

  it('each clause should maintain independent selection state', () => {
    const result = matchEach<Option<number>>({ kind: 'some', value: 1 })
      .with(
        { kind: 'some', value: P.select() },
        (value) => `first: ${value}`
      )
      .with({ kind: 'some' }, (value) => `second: ${value.value}`)
      .with(
        { kind: 'some', value: P.select() },
        (value) => `third: ${value}`
      )
      .exhaustive();

    expect(result).toStrictEqual([
      'first: 1',
      'second: 1',
      'third: 1',
    ]);
  });

  it('should build a reusable compiled matcher without a value argument', () => {
    const f = matchEach<number, string>()
      .with(P.even, (n) => `even: ${n}`)
      .with(P.odd, (n) => `odd: ${n}`)
      .toFunction();

    expect(f(2)).toStrictEqual(['even: 2']);
    expect(f(3)).toStrictEqual(['odd: 3']);
  });

  it('should support matchEach called with explicit type parameters and a value', () => {
    const f = matchEach<Country, string>('France')
      .with('France', 'Germany', () => 'Europe')
      .with('Spain', 'USA', () => 'elsewhere')
      .run();

    expect(f).toStrictEqual(['Europe']);
  });
});
