{"content": "import { matchEach, P, NonExhaustiveError } from '../src';

describe('matchEach edge cases', () => {
  it('should treat matchEach(undefined) as matching the undefined value', () => {
    const result = matchEach(undefined)
      .with(P.nullish, () => 'nullish')
      .otherwise(() => 'other');
    expect(result).toStrictEqual(['nullish']);
  });

  it('should allow compiling a matcher built without any value argument', () => {
    const f = matchEach<string>()
      .with('a', () => 'A')
      .toFunction();
    expect(f('a')).toStrictEqual(['A']);
    expect(f('b') as never).toBeUndefined; // not executed
    expect(() => f('b')).toThrow(NonExhaustiveError);
  });

  it('should throw a helpful error when running a value-less expression', () => {
    expect(() =>
      matchEach<string>()
        .with('a', () => 'A')
        .run()
    ).toThrow(/without a value/);
  });

  it('should execute taps inside toExhaustiveFunction and toPartialFunction', () => {
    const calls1: string[] = [];
    const ex = matchEach<number>()
      .with(P.number, (n) => `n: ${n}`)
      .tap((r) => calls1.push(r))
      .toExhaustiveFunction();
    expect(ex(5)).toStrictEqual(['n: 5']);
    expect(calls1).toStrictEqual(['n: 5']);

    const calls2: string[] = [];
    const partial = matchEach<string>()
      .with('a', (s) => `s: ${s}`)
      .tap((r) => calls2.push(r))
      .toPartialFunction();
    expect(partial('a')).toStrictEqual(['s: a']);
    expect(calls2).toStrictEqual(['s: a']);
    calls2.length = 0;
    expect(partial('b')).toBeUndefined();
    expect(calls2).toStrictEqual([]);
  });

  it('should support stacked taps on compiled functions', () => {
    const calls: string[] = [];
    const f = matchEach<number>()
      .with(P.number, (n) => `r1: ${n}`)
      .tap((r) => calls.push(`t1: ${r}`))
      .with(P.number.gt(0), (n) => `r2: ${n}`)
      .tap((r) => calls.push(`t2: ${r}`))
      .toFunction();

    expect(f(3)).toStrictEqual(['r1: 3', 'r2: 3']);
    expect(calls).toStrictEqual(['t1: r1: 3', 't2: r1: 3', 't2: r2: 3']);
  });

  it('should keep builder stages independent (no late clause leakage)', () => {
    const stage1 = matchEach<'a' | 'b'>('a').with('a', () => 'A');
    const stage2 = stage1.with('b', () => 'B');

    stage2.run();
    expect(stage1.run()).toStrictEqual(['A']);
    expect(stage2.run()).toStrictEqual(['A']);
  });

  it('should evaluate handlers in declaration order', () => {
    const order: string[] = [];
    matchEach('a' as 'a' | 'b')
      .with('a', () => {
        order.push('a');
        return 1;
      })
      .with('b', () => {
        order.push('b');
        return 2;
      })
      .run();
    expect(order).toStrictEqual(['a', 'b']);
  });
});
