```ts
async function* executeSingleAgent(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    yield { type: "error", error: `Agent '${agentId}' not found or provider not available` };
    return;
  }

  if (command?.command === "capture_screen") {
    yield* handleScreenCapture(...);
    return;
  }

  const delegationChain = [agentId];
  const context: ProviderContext[] = [];

  let providerRequest: ProviderChatRequest = {
    message: request.message,
    sessionId: request.sessionId,
    requestId: request.requestId,
    workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
    ...(context.length ? { context } : {}),
  };

  let toolUseCounter = 0;

  while (true) {
    let delegation: { toolUseId: string; agentId: string; instructions: string } | null = null;
    let done = false;

    for await (const response of provider.executeChat(providerRequest, {
      debugMode,
      abortController,
      temperature: agentConfig.config?.temperature,
      maxTokens: agentConfig.config?.maxTokens,
    })) {
      if (response.type === "tool_use" && response.toolName === DELEGATE_TASK_TOOL) {
        const toolUseId = `toolu_delegate_${request.requestId}_${toolUseCounter++}`;
        const input = (response.toolInput ?? {}) as { agent_id?: unknown; instructions?: unknown };

        // stream tool_use so its id can be matched against the tool_result
        yield {
          type: "claude_json",
          data: {
            type: "assistant",
            message: {
              role: "assistant",
              content: [
                {
                  type: "tool_use",
                  id: toolUseId,
                  name: DELEGATE_TASK_TOOL,
                  input: { agent_id: input.agent_id, instructions: input.instructions },
                },
              ],
            },
          },
        };

        delegation = {
          toolUseId,
          agentId: typeof input.agent_id === "string" ? input.agent_id : "",
          instructions: typeof input.instructions === "string" ? input.instructions : "",
        };
        continue;
      }

      // existing handling: chat room message
      const chatRoomMessage = createChatRoomMessage(response, agentId);
      if (chatRoomMessage) { yield {...} }

      if (response.type === "text") {
        yield { type: "claude_json", data: { type: "assistant", content: response.content, model: response.metadata?.model } };
      } else if (response.type === "done") {
        done = true;
      } else if (response.type === "error") {
        yield { type: "error", error: response.error };
        done = true;
      }
    }

    if (!delegation) return;  // conversation completed (or errored)

    // handle delegation
    const { toolUseId, agentId: targetAgentId, instructions } = delegation;

    // circular check
    if (delegationChain.includes(targetAgentId)) {
      yield { type: "error", error: `Circular delegation detected: ${targetAgentId} is already in the delegation chain (${delegationChain.join(" -> ")} -> ${targetAgentId})` };
      return;
    }

    const subProvider = globalRegistry.getProviderForAgent(targetAgentId);
    const subAgentConfig = globalRegistry.getAgent(targetAgentId);
    if (!subProvider || !subAgentConfig) {
      // unknown agent: stream error + error tool_result, re-invoke delegator so it sees it
      const toolResult = buildToolResult(toolUseId, true, `Delegation failed: agent '${targetAgentId}' not found or its provider is not available`);
      yield { type: "error", error: `Agent '${targetAgentId}' not found or provider not available` };
      context.push({ role: "user", content: JSON.stringify(toolResult) });
      providerRequest = { ...providerRequest, context: [...context] };
      continue;
    }

    // run sub-agent (recursively handling its own delegations)
    const subResult = await runSubAgent(targetAgentId, instructions, [...delegationChain, targetAgentId], request.requestId, abortController, debugMode);

    const toolResult = buildToolResult(toolUseId, !!subResult.error, subResult.text || subResult.error || DEFAULT_SUB_AGENT_OUTPUT);
    context.push({ role: "user", content: JSON.stringify(toolResult) });
    providerRequest = { ...providerRequest, context: [...context] };
    // re-invoke delegating agent so it can see the tool_result and continue
