 * Normalize delegate_task tool input into its expected shape
 */
function normalizeDelegationInput(toolInput: unknown): {
  agentId: string;
  instructions: string;
} {
  let input: unknown = toolInput;

  if (typeof input === "string") {
    try {
      input = JSON.parse(input);
    } catch {
      input = {};
    }
  }

  const record =
    input && typeof input === "object" ? (input as Record<string, unknown>) : {};

  const agentId =
    typeof record.agent_id === "string" && record.agent_id
      ? record.agent_id
      : typeof record.agentId === "string"
        ? record.agentId
        : "";

  const instructions =
    typeof record.instructions === "string" ? record.instructions : "";

  return { agentId, instructions };
}

/**
 * Generate a unique tool_use id for a delegate_task invocation
 */
function generateToolUseId(requestId: string, counter: number): string {
  return `toolu_delegate_${requestId}_${counter}`;
}

/**
 * Build the JSON string fed back to a delegating agent for a delegate_task tool use.
 * The delegating agent sees this tool_result when it is re-invoked.
 */
function buildToolResultJson(
  toolUseId: string,
  isError: boolean,
  content: string
): string {
  return JSON.stringify({
    type: "tool_result",
    is_error: isError,
    content,
    tool_use_id: toolUseId,
  });
}

/**
 * Create the streamed tool_use response for a delegate_task invocation
 */
function createToolUseStreamResponse(
  toolUseId: string,
  input: { agent_id: string; instructions: string },
  sessionId?: string
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "assistant",
      message: {
        role: "assistant",
        content: [
          {
            type: "tool_use",
            id: toolUseId,
            name: DELEGATE_TASK_TOOL,
            input,
          },
        ],
      },
      ...(sessionId ? { session_id: sessionId } : {}),
    },
  };
}

/**
 * Create the streamed tool_result response for a delegate_task invocation
 */
function createToolResultStreamResponse(
  toolUseId: string,
  content: string,
  isError: boolean,
  sessionId?: string
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "user",
