    }

    // Execute pending delegations and collect tool results to feed back
    const toolResults: string[] = [];
    let terminalError: string | undefined;

    for (const delegation of pendingDelegations) {
      // Circular delegation: the target is already in the delegation chain
      if (delegationChain.includes(delegation.agentId)) {
        terminalError = `Circular delegation detected: agent '${delegation.agentId}' is already in the delegation chain (${[...delegationChain, delegation.agentId].join(" -> ")})`;
        break;
      }

      // Depth guard against unbounded recursive delegation
      if (delegationChain.length >= MAX_DELEGATION_DEPTH) {
        terminalError = `Maximum delegation depth of ${MAX_DELEGATION_DEPTH} exceeded`;
        break;
      }

      // Guard against unbounded repeated delegations
      delegationCount.value++;
      if (delegationCount.value > MAX_DELEGATIONS_PER_RUN) {
        terminalError = `Maximum number of delegations (${MAX_DELEGATIONS_PER_RUN}) exceeded`;
        break;
      }

      const subProvider = globalRegistry.getProviderForAgent(delegation.agentId);
      const subAgentConfig = globalRegistry.getAgent(delegation.agentId);

      if (!subProvider || !subAgentConfig) {
        // Unknown agent: emit a stream error and an is_error tool_result
        const errorContent = `Delegation failed: agent '${delegation.agentId}' not found or its provider is not available`;

        yield createToolResultStreamResponse(
          delegation.toolUseId,
          errorContent,
          true,
          sessionId
        );

        terminalError = `Agent '${delegation.agentId}' not found or provider not available`;
        break;
      }

      // Run the sub-agent on the delegated instructions (recursively handling
      // its own delegations). Sub-agent activity is not streamed to the
      // client; only its accumulated output is fed back.
      const subOutput: AgentOutput = { text: "" };
      let subProtocolError: string | undefined;
      let subRunFailed = false;

      try {
        for await (const subResponse of executeAgentWithDelegation(
          delegation.agentId,
          delegation.instructions,
          subAgentConfig.workingDirectory,
          [...delegationChain, delegation.agentId],
          request,
          abortController,
          debugMode,
          undefined,
          subOutput
        )) {
          if (subResponse.type === "error") {
            // Terminal protocol failure (circular delegation, unknown agent,
            // depth exceeded): propagate it to the top-level stream
            subProtocolError = subResponse.error;
            break;
          }
        }
      } catch (error) {
        subRunFailed = true;
        subOutput.error = error instanceof Error ? error.message : String(error);
      }

      if (subProtocolError) {
        terminalError = subProtocolError;
        break;
      }

      // Feed back a single tool_result: the sub-agent's accumulated textual
      // output, an error message if the run failed, or a placeholder
      const isError = subRunFailed || !!subOutput.error;
      const content = isError
        ? (subOutput.error || "Sub-agent execution failed")
        : (subOutput.text.trim() || EMPTY_SUB_AGENT_OUTPUT);
      const toolResultJson = buildToolResultJson(delegation.toolUseId, isError, content);

      toolResults.push(toolResultJson);

      if (debugMode) {
        console.debug(`[Multi-Agent] Fed tool result back for delegation to '${delegation.agentId}'`, {
          toolUseId: delegation.toolUseId,
          isError,
          content: content.substring(0, 100),
        });
      }

      yield createToolResultStreamResponse(
        delegation.toolUseId,
        content,
        isError,
        sessionId
      );
    }

    if (terminalError) {
      if (output) {
        output.error = output.error || terminalError;
      }

      yield { type: "error", error: terminalError };
      return;
    }

    // Re-invoke the delegating agent so it sees the tool_result(s) and the
    // conversation can continue
    for (const toolResultJson of toolResults) {
      context.push({ role: "user", content: toolResultJson });
    }
  }
}

/**
 * Execute chat with a single agent
 */
async function* executeSingleAgent(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  // Handle special commands
  if (command?.command === "capture_screen") {
    yield* handleScreenCapture(agentId, request, command, abortController, debugMode);
    return;
  }

  // Execute with delegation support (unknown agents are reported by the
  // delegation core)
  yield* executeAgentWithDelegation(
    agentId,
    request.message,
    request.workingDirectory,
    [agentId],
    request,
    abortController,
    debugMode,
    request.sessionId
  );
