// typeConstraintError makes the type error for assigning a value of source
// type to a variable of constraint type.
func typeConstraintError(name string, sourceType string, constraint reflect.Type) error {
	return fmt.Errorf("type error: cannot assign value of type %s to variable %s of type %s", sourceType, name, constraint)
}

// checkTypeConstraint returns an error when value cannot be assigned to a
// variable with the given type constraint. The blank identifier is exempt
// from constraint checking. No implicit type conversion is performed,
// interface constraints accept any value that satisfies the interface, and
// nil is only valid for interface, slice, map, pointer, and channel types.
func checkTypeConstraint(name string, value reflect.Value, constraint reflect.Type) error {
	if name == "_" || constraint == nil {
		return nil
	}

	source := value
	sourceIsNil := isNil(value)
	if !sourceIsNil && value.Kind() == reflect.Interface {
		source = value.Elem()
	}

	if sourceIsNil {
		switch constraint.Kind() {
		case reflect.Interface, reflect.Slice, reflect.Map, reflect.Ptr, reflect.Chan:
			return nil
		}
		return typeConstraintError(name, "<nil>", constraint)
	}

	if source.Type() == constraint {
		return nil
	}
	if constraint.Kind() == reflect.Interface && source.Type().AssignableTo(constraint) {
		return nil
	}
	return typeConstraintError(name, source.Type().String(), constraint)
