import (
	"reflect"
	"testing"
)

func TestDefineValueWithConstraint(t *testing.T) {
	constraint := reflect.TypeOf(int64(0))
	envTest := NewEnv()

	err := envTest.DefineValueWithConstraint("a", reflect.ValueOf(int64(1)), constraint)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}

	value, err := envTest.Get("a")
	if err != nil {
		t.Fatalf("Get error: %v", err)
	}
	if v, ok := value.(int64); !ok || v != int64(1) {
		t.Fatalf("value - received: %v - expected: %v", value, int64(1))
	}

	c, ok := envTest.Constraint("a")
	if !ok {
		t.Fatalf("Constraint - received: %v - expected: constraint found", c)
	}
	if c != constraint {
		t.Fatalf("constraint - received: %v - expected: %v", c, constraint)
	}
}

func TestConstraintParentLookup(t *testing.T) {
	constraint := reflect.TypeOf(int64(0))
	envParent := NewEnv()
	envChild := envParent.NewEnv()

	err := envParent.DefineValueWithConstraint("a", reflect.ValueOf(int64(1)), constraint)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}

	c, ok := envChild.Constraint("a")
	if !ok {
		t.Fatalf("Constraint - received: %v - expected: constraint found", c)
	}
	if c != constraint {
		t.Fatalf("constraint - received: %v - expected: %v", c, constraint)
	}
}

func TestConstraintNewBinding(t *testing.T) {
	constraint := reflect.TypeOf(int64(0))
	envParent := NewEnv()
	envChild := envParent.NewEnv()

	err := envParent.DefineValueWithConstraint("a", reflect.ValueOf(int64(1)), constraint)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}

	// new binding in child scope must not inherit the parent constraint
	err = envChild.DefineValueWithConstraint("a", reflect.ValueOf("a"), nil)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}

	c, ok := envChild.Constraint("a")
	if ok {
		t.Fatalf("Constraint - received: %v - expected: no constraint", c)
	}

	// parent constraint is untouched
	c, ok = envParent.Constraint("a")
	if !ok {
		t.Fatalf("Constraint - received: %v - expected: constraint found", c)
	}
	if c != constraint {
		t.Fatalf("constraint - received: %v - expected: %v", c, constraint)
	}
}

func TestConstraintReplaced(t *testing.T) {
	constraint := reflect.TypeOf(int64(0))
	envTest := NewEnv()

	err := envTest.DefineValueWithConstraint("a", reflect.ValueOf(int64(1)), constraint)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}

	// redefinition without constraint removes the previous constraint
	err = envTest.DefineValueWithConstraint("a", reflect.ValueOf("a"), nil)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}

	if c, ok := envTest.Constraint("a"); ok {
		t.Fatalf("Constraint - received: %v - expected: no constraint", c)
	}

	// DefineValue also removes the previous constraint
	err = envTest.DefineValueWithConstraint("a", reflect.ValueOf(int64(1)), constraint)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}
	err = envTest.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatalf("DefineValue error: %v", err)
	}
	if c, ok := envTest.Constraint("a"); ok {
		t.Fatalf("Constraint - received: %v - expected: no constraint", c)
	}
}

func TestConstraintDelete(t *testing.T) {
	constraint := reflect.TypeOf(int64(0))
	envTest := NewEnv()

	err := envTest.DefineValueWithConstraint("a", reflect.ValueOf(int64(1)), constraint)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}

	envTest.Delete("a")

	if c, ok := envTest.Constraint("a"); ok {
		t.Fatalf("Constraint - received: %v - expected: no constraint", c)
	}
}

func TestConstraintCopy(t *testing.T) {
	constraint := reflect.TypeOf(int64(0))
	envTest := NewEnv()

	err := envTest.DefineValueWithConstraint("a", reflect.ValueOf(int64(1)), constraint)
	if err != nil {
		t.Fatalf("DefineValueWithConstraint error: %v", err)
	}

	c, ok := envTest.Copy().Constraint("a")
	if !ok {
		t.Fatalf("Constraint - received: %v - expected: constraint found", c)
	}
	if c != constraint {
		t.Fatalf("constraint - received: %v - expected: %v", c, constraint)
	}

	c, ok = envTest.DeepCopy().Constraint("a")
	if !ok {
		t.Fatalf("Constraint - received: %v - expected: constraint found", c)
	}
	if c != constraint {
		t.Fatalf("constraint - received: %v - expected: %v", c, constraint)
	}
}
