func TestTypedBindings(t *testing.T) {
	t.Parallel()

	tests := []Test{
		{Script: `var x: int64 = 10`, Output: map[string]interface{}{"x": int64(10)}},
		{Script: `var x: int64 = 10; x`, RunOutput: int64(10)},
