		{Script: `var a, b: int64`, Output: map[string]interface{}{"a": int64(0), "b": int64(0)}},
		{Script: `var a, b: int64 = [1, 2]; a + b`, RunOutput: int64(3)},

		{Script: `var x: string = "a"; x`, RunOutput: "a"},
		{Script: `var x: float64 = 1.1; x`, RunOutput: float64(1.1)},
		{Script: `var x: bool = true; x`, RunOutput: true},

