func TestTypedBindingsDisabled(t *testing.T) {
	t.Parallel()

	tests := []Test{
		// typed declaration syntax still parses and executes
		{Script: `var x: int64 = 10; x`, RunOutput: int64(10)},
		{Script: `var x: int64; x`, RunOutput: int64(0)},
		{Script: `var a, b: int64 = 1, 2; a + b`, RunOutput: int64(3)},

		// constraint enforcement is not applied
		{Script: `var x: int64 = "a"; x`, RunOutput: "a"},
		{Script: `var x: int64 = 10; x = "a"; x`, RunOutput: "a"},
		{Script: `var x: float64 = 1; x`, RunOutput: int64(1)},
		{Script: `var x: int64 = nil; x`, RunOutput: nil},
		{Script: `var x: string = nil; x`, RunOutput: nil},
		{Script: `var x: int64 = 10; x = nil; x`, RunOutput: nil},

		// unknown type still errors
		{Script: `var x: foo = 1`, RunError: fmt.Errorf("undefined type 'foo'")},

		// untyped declarations remain dynamically typed
		{Script: `var x = 10; x = "a"; x`, RunOutput: "a"},
		{Script: `var x = nil; x = 10; x`, RunOutput: int64(10)},
	}
	runTests(t, tests, nil, &Options{TypedBindings: false})
}
