+// DefineValueWithConstraint defines/sets reflect value to symbol in current
+// scope. The new binding gets the given type constraint, or no constraint when
+// constraint is nil (replacing any previous constraint on the binding).
+func (e *Env) DefineValueWithConstraint(symbol string, value reflect.Value, constraint reflect.Type) error {
+	if strings.Contains(symbol, ".") {
+		return ErrSymbolContainsDot
+	}
+	e.rwMutex.Lock()
+	e.values[symbol] = value
+	if constraint != nil {
+		if e.constraints == nil {
+			e.constraints = make(map[string]reflect.Type)
+		}
+		e.constraints[symbol] = constraint
+	} else if e.constraints != nil {
+		delete(e.constraints, symbol)
+	}
 	e.rwMutex.Unlock()

 	return nil
 }

+// Constraint returns the type constraint of the first binding of symbol found
+// in current or parent scope. The second return value reports whether the
+// binding has a constraint.
+func (e *Env) Constraint(symbol string) (reflect.Type, bool) {
+	for env := e; env != nil; env = env.parent {
+		env.rwMutex.RLock()
+		if _, ok := env.values[symbol]; ok {
+			constraint, found := env.constraints[symbol]
+			env.rwMutex.RUnlock()
+			return constraint, found
+		}
+		env.rwMutex.RUnlock()
+	}
+	return nil, false
+}
