+// variable with the given type constraint. The blank identifier is exempt
+// from constraint checking. No implicit type conversion is performed,
+// interface constraints accept any value that satisfies the interface, and
+// nil is only valid for interface, slice, map, pointer, and channel types.
+func checkTypeConstraint(name string, value reflect.Value, constraint reflect.Type) error {
+	if name == "_" || constraint == nil {
+		return nil
+	}
+
+	source := value
+	sourceIsNil := !value.IsValid() || isNil(value)
+	if !sourceIsNil && value.Kind() == reflect.Interface {
+		source = value.Elem()
+	}
+
+	if sourceIsNil {
+		switch constraint.Kind() {
