+			return nil
+		}
+		return typeConstraintError(name, "<nil>", constraint)
+	}
+
+	if source.Type() == constraint {
+		return nil
+	}
+	if constraint.Kind() == reflect.Interface && source.Type().AssignableTo(constraint) {
+		return nil
+	}
+	return typeConstraintError(name, source.Type().String(), constraint)
