{"content": """"
raw feature schema: validation of the `dataset.features` configuration,
selection of raw features during fit and application of the persisted
schema before any model call (evaluate, predict, /predict)
"""

import logging
import os

import joblib
import pandas as pd

logger = logging.getLogger(__name__)

FEATURES_KEYS = ("include", "exclude", "drop_constant", "drop_duplicate")


class FeatureConfigError(Exception):
    """Raised when the `dataset.features` configuration is invalid."""


class FeatureSchemaError(Exception):
    """Raised when data does not comply with a persisted feature schema."""


def _as_name_list(value, option):
    """
    normalize a single column name or a list of column names to a list
    @param value: option value from the yaml configuration
    @param option: name of the option (include/exclude) used in error messages
    @return: list of feature names or None
    """
    if value is None:
        return None
    if isinstance(value, str):
        candidates = [value]
    elif isinstance(value, (list, tuple)):
        candidates = list(value)
    else:
        raise FeatureConfigError(
            f"{option} must be a single column name or a list of column names"
        )
    if not candidates:
        raise FeatureConfigError(
            f"{option} must contain at least one non-empty feature name"
        )
    for name in candidates:
        if not isinstance(name, str) or not name.strip():
            raise FeatureConfigError(
                f"{option} must contain unique non-empty feature names"
            )
    duplicates = sorted(
        {name for name in candidates if candidates.count(name) > 1}
    )
    if duplicates:
        raise FeatureConfigError(f"duplicate entries in {option}: {duplicates}")
    return candidates


def validate_features_config(features_props, raw_columns, target_columns):
    """
    validate the raw `dataset.features` configuration against the dataset
    @param features_props: value of dataset.features from the yaml file
    @param raw_columns: columns of the raw dataset
    @param target_columns: target column(s) of the model
    @return: normalized configuration dictionary
    """
    if features_props in (None, {}):
        return {
            "include": None,
            "exclude": None,
            "drop_constant": False,
            "drop_duplicate": False,
        }
    if not isinstance(features_props, dict):
        raise FeatureConfigError(
            f"dataset.features must be a dictionary with keys: {list(FEATURES_KEYS)}"
        )
    unknown_options = [
        key for key in features_props.keys() if key not in FEATURES_KEYS
    ]
    if unknown_options:
        raise FeatureConfigError(
            f"unknown dataset.features option(s): {sorted(unknown_options)}. "
            f"supported options are: {list(FEATURES_KEYS)}"
        )

    include = _as_name_list(features_props.get("include"), "include")
    exclude = _as_name_list(features_props.get("exclude"), "exclude")
    drop_constant = features_props.get("drop_constant", False)
    drop_duplicate = features_props.get("drop_duplicate", False)
    if not isinstance(drop_constant, bool):
        raise FeatureConfigError(
            "dataset.features.drop_constant must be a boolean"
        )
    if not isinstance(drop_duplicate, bool):
        raise FeatureConfigError(
            "dataset.features.drop_duplicate must be a boolean"
        )

    raw_set = set(raw_columns)
    targets = set(target_columns or [])
    for option, names in (("include", include), ("exclude", exclude)):
        if names is None:
            continue
        target_hits = [name for name in names if name in targets]
        if target_hits:
            raise FeatureConfigError(
                f"target column(s) cannot be used in {option}: {target_hits}"
            )
        unknown_names = [name for name in names if name not in raw_set]
        if unknown_names:
            raise FeatureConfigError(
                f"unknown feature(s) in {option}: {unknown_names}. "
                f"available raw features: {list(raw_columns)}"
            )
    return {
        "include": include,
        "exclude": exclude,
        "drop_constant": drop_constant,
        "drop_duplicate": drop_duplicate,
    }


def _is_constant(series):
    """
    a column is constant when it holds at most one unique value
    (an all-missing column is considered constant as well)
    """
    return series.nunique(dropna=True) <= 1


def select_raw_features(df, features_props, target_columns):
    """
    select the raw feature columns used as model inputs during fit
    @param df: raw dataset
    @param features_props: value of dataset.features from the yaml file
    @param target_columns: target column(s) of the model
    @return: tuple of the selected dataframe and the feature schema
    """
    raw_columns = list(df.columns)
    props = validate_features_config(features_props, raw_columns, target_columns)

    pool = list(props["include"]) if props["include"] else list(raw_columns)
    excluded = [name for name in (props["exclude"] or []) if name in pool]
    pool = [name for name in pool if name not in set(excluded)]
    dropped_features = {"excluded": excluded, "constant": [], "duplicate": []}

    if not pool:
        raise FeatureConfigError(
            "feature configuration removes every feature: "
            f"no input feature left in {raw_columns}"
        )

    if props["drop_constant"]:
        constant = [name for name in pool if _is_constant(df[name])]
        if len(constant) == len(pool):
            raise FeatureConfigError(
                "feature configuration removes every feature: "
                f"all remaining features {pool} are constant"
            )
        dropped_features["constant"] = constant
        pool = [name for name in pool if name not in set(constant)]

    duplicate_feature_aliases = {}
    if props["drop_duplicate"]:
        duplicates = []
        canonical_columns = []
        for name in pool:
            canonical = next(
                (ref for ref in canonical_columns if df[ref].equals(df[name])),
                None,
            )
            if canonical is None:
                canonical_columns.append(name)
            else:
                duplicates.append(name)
                duplicate_feature_aliases.setdefault(canonical, []).append(name)
        dropped_features["duplicate"] = duplicates
        pool = canonical_columns

    schema = {
        "input_features": pool,
        "dropped_features": dropped_features,
        "duplicate_feature_aliases": duplicate_feature_aliases,
    }
    logger.info(f"selected raw feature schema: {schema}")
    return df[pool], schema


def apply_feature_schema(df, schema, keep_columns=None):
    """
    apply a persisted feature schema to raw data before any model call
    extra raw columns are ignored, any recorded alias may satisfy its
    canonical feature and all provided sources of the same feature must
    agree row-wise for every row
    @param df: raw dataset
    @param schema: persisted feature schema
    @param keep_columns: extra columns (e.g. targets) kept after the features
    @return: dataframe holding the schema features in the persisted order
    """
    if not schema or not schema.get("input_features"):
        raise FeatureSchemaError(
            "no persisted feature schema found. please re-run fit to store it"
        )
    input_features = list(schema["input_features"])
    aliases = schema.get("duplicate_feature_aliases") or {}
    keep_columns = [col for col in (keep_columns or []) if col in df.columns]

    missing = []
    conflicts = {}
    for feature in input_features:
        sources = [feature] + [
            alias for alias in aliases.get(feature, []) if alias in df.columns
        ]
        available = [source for source in sources if source in df.columns]
        if not available:
            missing.append(feature)
            continue
        for index, source in enumerate(available[1:], start=1):
            if not df[available[0]].equals(df[source]):
                conflicts[feature] = available

    if missing:
        raise FeatureSchemaError(f"missing required feature(s): {missing}")
    if conflicts:
        raise FeatureSchemaError(
            "duplicate feature sources do not agree row-wise for every row: "
            f"{list(conflicts.values())}"
        )

    frames = [df[feature] for feature in input_features]
    frames += [df[col] for col in keep_columns]
    selected = pd.concat(frames, axis=1)
    logger.info(
        f"feature schema applied. selected features: {input_features}"
    )
    return selected


def save_feature_schema(schema, path):
    """
    persist the feature schema to a joblib file
    @param schema: feature schema dictionary
    @param path: destination file path
    @return: path where the schema was stored
    """
    joblib.dump(schema, path)
    logger.info(f"feature schema saved to {path}")
    return path


def load_feature_schema(path):
    """
    load a persisted feature schema
    @param path: path of the feature schema file
    @return: feature schema dictionary
    """
    if not path or not os.path.exists(path):
        raise FeatureSchemaError(
            f"feature schema file not found at {path}. "
            f"please re-run fit to store it"
        )
    schema = joblib.load(path)
    if not isinstance(schema, dict) or not schema.get("input_features"):
        raise FeatureSchemaError(f"invalid feature schema file at {path}")
    return schema
