	if ew.closed {
		return 0, errClosed
	}
	ew.buf = append(ew.buf, p...)
	total := 0
	for len(ew.buf) >= chunkSize {
		chunk := make([]byte, chunkSize)
		copy(chunk, ew.buf)
		ew.buf = ew.buf[chunkSize:]  // hmm, need to be careful about aliasing
		n, err := ew.writeChunk(chunk)
		...
	}
