}
```

Wait — but writeChunk does HMAC on the encoded chunk bytes and writes to w. Error handling: keep it simple, return the error from Write.

writeChunk:
```go
func (ew *EncryptWriter) writeChunk(plaintext []byte) error {
	nonce := make([]byte, nonceSize)
	if _, err := rand.Read(nonce); err != nil {
		return fmt.Errorf("generate nonce: %w", err)
	}
	sealed := ew.e.gcm.Seal(nil, nonce, plaintext, nil)
	encoded := make([]byte, 4+nonceSize+len(sealed))
	binary.BigEndian.PutUint32(encoded, uint32(nonceSize+len(sealed)))
	copy(encoded[4:], nonce)
	copy(encoded[4+nonceSize:], sealed)
	ew.h.Write(encoded)
	_, err := ew.w.Write(encoded)
	return err
}
```

