```go
func DecryptReader(r io.Reader, key []byte) (io.Reader, error) {
	if len(key) != keySize {
		return nil, fmt.Errorf("%w: key must be %d bytes, got %d", ErrInvalidKey, keySize, len(key))
	}
	return &decryptReader{
		r:   r,
		key: key,
		h:   hmac.New(sha256.New, key),
	}, nil
}

type decryptReader struct {
	r       io.Reader
	key     []byte
	gcm     cipher.AEAD
	h       hash.Hash
	plain   bytes.Buffer
	ready   bool // header read and cipher initialized
	drained bool // sentinel + mac verified
	err     error
}

func (d *decryptReader) init() error {
	if d.err != nil {
		return d.err
	}
	if d.ready {
		return nil
	}
	hdr := make([]byte, headerSize)
	if _, err := io.ReadFull(d.r, hdr); err != nil {
		d.err = fmt.Errorf("invalid header: %w", err)
		return d.err
	}
	if hdr[0] != 0x4F || hdr[1] != 0x44 {
		d.err = errors.New("invalid header: bad magic bytes")
		return d.err
	}
	if hdr[2] != version {
		d.err = fmt.Errorf("unsupported version: got 0x%02x, want 0x01", hdr[2])
		return d.err
	}
