func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()
		prs = append(prs, pr)

		w := pw
		if compress {
			gw := gzip.NewWriter(w)
			pcs = append(pcs, gw)
			w = gw
		}
		if encryptor != nil {
			ew := encryptor.EncryptWriter(w)
			pcs = append(pcs, ew)
			w = ew
		}
		pws = append(pws, w)
		pcs = append(pcs, pw)
	}
	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
}
