func (e *Encryptor) EncryptWriter(w io.Writer) io.WriteCloser {
	return &encryptWriter{
		encryptor: e,
		w:         w,
		mac:       hmac.New(sha256.New, e.key),
	}
}

type encryptWriter struct {
	encryptor *Encryptor
	w         io.Writer
	mac       hash.Hash
	buf       []byte
	started   bool
	closed    bool
	err       error
}

func (ew *encryptWriter) Write(p []byte) (int, error) {
	if ew.closed {
		return 0, errWriterClosed
	}
	if ew.err != nil {
		return 0, ew.err
	}

	if !ew.started {
		if _, err := ew.w.Write(headerBytes); err != nil {
			ew.err = fmt.Errorf("write stream header: %w", err)
			return 0, ew.err
		}
		ew.started = true
	}

	ew.buf = append(ew.buf, p...)

	for len(ew.buf) >= MaxChunkSize {
		chunk := append([]byte(nil), ew.buf[:MaxChunkSize]...)
		if err := ew.writeChunk(chunk); err != nil {
			ew.err = err
			return 0, err
		}
		ew.buf = ew.buf[MaxChunkSize:]
	}

	return len(p), nil
}

func (ew *encryptWriter) writeChunk(plaintext []byte) error {
	nonce := make([]byte, nonceSize)
	if _, err := rand.Read(nonce); err != nil {
		return fmt.Errorf("generate nonce: %w", err)
	}

	sealed := ew.encryptor.gcm.Seal(nil, nonce, plaintext, nil)

	encoded := make([]byte, lengthSize+nonceSize+len(sealed))
	binary.BigEndian.PutUint32(encoded, uint32(nonceSize+len(sealed)))
	copy(encoded[lengthSize:], nonce)
	copy(encoded[lengthSize+nonceSize:], sealed)

	ew.mac.Write(encoded)

	if _, err := ew.w.Write(encoded); err != nil {
		return fmt.Errorf("write chunk: %w", err)
	}

	return nil
}

func (ew *encryptWriter) Close() error {
	if ew.closed {
		return nil
	}
	ew.closed = true
	if ew.err != nil {
		return ew.err
	}

	var errs error

	if !ew.started {
		_, err := ew.w.Write(headerBytes)
		errs = errors.Join(errs, err)
	}

	if len(ew.buf) > 0 {
		errs = errors.Join(errs, ew.writeChunk(ew.buf))
		ew.buf = nil
	}

	if _, err := ew.w.Write(sentinelBytes); err != nil {
		errs = errors.Join(errs, fmt.Errorf("write sentinel: %w", err))
	}

	mac := ew.mac.Sum(nil)
	if _, err := ew.w.Write(mac); err != nil {
		errs = errors.Join(errs, fmt.Errorf("write hmac: %w", err))
	}

	return errs
}

type decryptReader struct {
	r       io.Reader
	key     []byte
	gcm     cipher.AEAD
	mac     hash.Hash
	plain   bytes.Buffer
	ready   bool
	drained bool
	err     error
}

// DecryptReader returns an io.Reader that reverses the stream produced by
// EncryptWriter. Initialization is lazy: header parsing, cipher setup and
// the final HMAC verification all happen during Read, so any stream error
// surfaces there.
func DecryptReader(r io.Reader, key []byte) (io.Reader, error) {
	if len(key) != KeySize {
		return nil, fmt.Errorf("%w: key must be %d bytes, got %d", ErrInvalidKey, KeySize, len(key))
	}

	return &decryptReader{
		r:   r,
		key: key,
		mac: hmac.New(sha256.New, key),
	}, nil
}

func (d *decryptReader) init() error {
	if d.err != nil {
		return d.err
	}
	if d.ready {
		return nil
	}

	header := make([]byte, headerSize)
	if _, err := io.ReadFull(d.r, header); err != nil {
		d.err = fmt.Errorf("invalid header: %w", err)
		return d.err
	}

	if header[0] != magic0 || header[1] != magic1 {
		d.err = fmt.Errorf("invalid header: unexpected magic bytes 0x%02x 0x%02x", header[0], header[1])
		return d.err
	}

	if header[2] != version {
		d.err = fmt.Errorf("unsupported version: got 0x%02x, want 0x%02x", header[2], version)
		return d.err
	}

	block, err := aes.NewCipher(d.key)
	if err != nil {
		d.err = fmt.Errorf("create aes cipher: %w", err)
		return d.err
	}

	d.gcm = cipher.NewGCM(block)
	d.ready = true

	return nil
}

// fill decrypts the next chunk into the plaintext buffer, or verifies the
// trailing HMAC once the sentinel is reached.
func (d *decryptReader) fill() error {
	if d.err != nil {
		return d.err
	}
	if d.drained {
		return nil
	}

	lengthBuf := make([]byte, lengthSize)
	if _, err := io.ReadFull(d.r, lengthBuf); err != nil {
		d.err = fmt.Errorf("read chunk length: %w", err)
		return d.err
	}

	chunkLen := binary.BigEndian.Uint32(lengthBuf)
	if chunkLen == sentinelLen {
		mac := make([]byte, hmacSize)
		if _, err := io.ReadFull(d.r, mac); err != nil {
			d.err = fmt.Errorf("read hmac: %w", err)
			return d.err
		}

		expected := d.mac.Sum(nil)
		if !hmac.Equal(mac, expected) {
			d.err = errors.New("integrity check failed: hmac mismatch")
			return d.err
		}

		d.drained = true
		return nil
	}

	if chunkLen < nonceSize+tagSize {
		d.err = fmt.Errorf("malformed chunk: length %d is smaller than nonce plus tag", chunkLen)
		return d.err
	}

	chunk := make([]byte, chunkLen)
	if _, err := io.ReadFull(d.r, chunk); err != nil {
		d.err = fmt.Errorf("read chunk: %w", err)
		return d.err
	}

	d.mac.Write(append(append([]byte{}, lengthBuf...), chunk...))

	nonce := chunk[:nonceSize]
	sealed := chunk[nonceSize:]

	plaintext, err := d.gcm.Open(nil, nonce, sealed, nil)
	if err != nil {
		d.err = fmt.Errorf("decrypt chunk: %w", err)
		return d.err
	}

	_, err = d.plain.Write(plaintext)
	if err != nil {
		d.err = fmt.Errorf("buffer plaintext: %w", err)
		return d.err
	}

	return nil
}

func (d *decryptReader) Read(p []byte) (int, error) {
	for {
		if d.err != nil {
			return 0, d.err
		}

		if d.plain.Len() > 0 {
			return d.plain.Read(p)
		}

		if d.drained {
			return 0, io.EOF
		}

		if err := d.init(); err != nil {
			return 0, err
		}

		if err := d.fill(); err != nil {
			return 0, err
		}
	}
}
