{"content": "package encryption

import (
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"strings"

	"golang.org/x/crypto/pbkdf2"
)

// Supported key sources.
const (
	KeySourceEnv     = "env"
	KeySourceFile    = "file"
	KeySourceLiteral = "literal"
	KeySourceDerive  = "derive"

	minSaltSize = 16
)

// Config configures dump encryption.
type Config struct {
	Enabled    bool   `yaml:"enabled"`
	KeySource  string `yaml:"keysource"`
	KeyEnvVar  string `yaml:"keyenvvar"`
	KeyFile    string `yaml:"keyfile"`
	Key        string `yaml:"key"`
	Passphrase string `yaml:"passphrase"`
	Salt       string `yaml:"salt"`
}

func normalizeSource(source string) string {
	return strings.ToLower(strings.TrimSpace(source))
}

// Validate checks the encryption configuration. A disabled configuration is
// always valid. When enabled the key source must be one of env, file,
// literal or derive (case-insensitive) and only the fields belonging to that
// source may be set.
func (c Config) Validate() error {
	if !c.Enabled {
		return nil
	}

	source := normalizeSource(c.KeySource)
	if source == "" {
		return errors.New("encryption key source is required when encryption is enabled")
	}

	switch source {
	case KeySourceEnv:
		if strings.TrimSpace(c.KeyEnvVar) == "" {
			return fmt.Errorf("key env var is required for key source %q", KeySourceEnv)
		}
	case KeySourceFile:
		if strings.TrimSpace(c.KeyFile) == "" {
			return fmt.Errorf("key file is required for key source %q", KeySourceFile)
		}
	case KeySourceLiteral:
		if strings.TrimSpace(c.Key) == "" {
			return fmt.Errorf("inline key is required for key source %q", KeySourceLiteral)
		}
	case KeySourceDerive:
		if strings.TrimSpace(c.Passphrase) == "" {
			return fmt.Errorf("passphrase is required for key source %q", KeySourceDerive)
		}
		salt, err := base64.StdEncoding.DecodeString(strings.TrimSpace(c.Salt))
		if err != nil {
			return fmt.Errorf("salt must be valid base64 for key source %q: %w", KeySourceDerive, err)
		}
		if len(salt) < minSaltSize {
			return fmt.Errorf("salt must be at least %d bytes for key source %q, got %d", minSaltSize, KeySourceDerive, len(salt))
		}
	default:
		return fmt.Errorf("unsupported encryption key source %q", c.KeySource)
	}

	for _, other := range []struct {
		name  string
		value string
	}{
		{"key env var", c.KeyEnvVar},
		{"key file", c.KeyFile},
		{"inline key", c.Key},
		{"passphrase", c.Passphrase},
		{"salt", c.Salt},
	} {
		if source == KeySourceEnv && other.name == "key env var" {
			continue
		}
		if source == KeySourceFile && other.name == "key file" {
			continue
		}
		if source == KeySourceLiteral && other.name == "inline key" {
			continue
		}
		if source == KeySourceDerive && (other.name == "passphrase" || other.name == "salt") {
			continue
		}
		if strings.TrimSpace(other.value) != "" {
			return fmt.Errorf("encryption field %q is mutually exclusive with key source %q", other.name, source)
		}
	}

	return nil
}

// LoadKey loads the 32-byte encryption key described by cfg.
func LoadKey(cfg Config) ([]byte, error) {
	if !cfg.Enabled {
		return nil, errors.New("encryption is not enabled")
	}

	if err := cfg.Validate(); err != nil {
		return nil, err
	}

	source := normalizeSource(cfg.KeySource)

	var key []byte
	var err error

	switch source {
	case KeySourceEnv:
		value, ok := os.LookupEnv(cfg.KeyEnvVar)
		if !ok {
			return nil, fmt.Errorf("encryption key env var %q is not set", cfg.KeyEnvVar)
		}
		key, err = base64.StdEncoding.DecodeString(strings.TrimSpace(value))
		if err != nil {
			return nil, fmt.Errorf("decode encryption key from env var %q: %w", cfg.KeyEnvVar, err)
		}
	case KeySourceFile:
		content, err := os.ReadFile(cfg.KeyFile)
		if err != nil {
			return nil, fmt.Errorf("read encryption key file %q: %w", cfg.KeyFile, err)
		}
		key, err = base64.StdEncoding.DecodeString(strings.TrimSpace(string(content)))
		if err != nil {
			return nil, fmt.Errorf("decode encryption key from file %q: %w", cfg.KeyFile, err)
		}
	case KeySourceLiteral:
		key, err = base64.StdEncoding.DecodeString(strings.TrimSpace(cfg.Key))
		if err != nil {
			return nil, fmt.Errorf("decode inline encryption key: %w", err)
		}
	case KeySourceDerive:
		salt, err := base64.StdEncoding.DecodeString(strings.TrimSpace(cfg.Salt))
		if err != nil {
			return nil, fmt.Errorf("decode salt: %w", err)
		}
		if len(salt) < minSaltSize {
			return nil, fmt.Errorf("salt must be at least %d bytes, got %d", minSaltSize, len(salt))
		}
		if strings.TrimSpace(cfg.Passphrase) == "" {
			return nil, errors.New("passphrase is required to derive an encryption key")
		}
		key = deriveKey(cfg.Passphrase, salt)
	default:
		return nil, fmt.Errorf("unsupported encryption key source %q", cfg.KeySource)
	}

	if len(key) != KeySize {
		return nil, fmt.Errorf("%w: key must be %d bytes, got %d", ErrInvalidKey, KeySize, len(key))
	}

	return key, nil
}

// deriveKey deterministically derives a 32-byte key from a passphrase and a
// salt using PBKDF2-HMAC-SHA256 with a fixed iteration count.
func deriveKey(passphrase string, salt []byte) []byte {
	const iterations = 65536
	return pbkdf2.Key([]byte(passphrase), salt, iterations, KeySize, sha256New)
}
