// When encryptor is non-nil, the streamed content is AES-256-GCM encrypted
// on top of the optional gzip layer before reaching the pipe.
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		w := pw
		if compress {
			gw := gzip.NewWriter(w)
			pcs = append(pcs, gw)
			w = gw
		}

		if encryptor != nil {
			ew := encryptor.EncryptWriter(w)
			pcs = append(pcs, ew)
			w = ew
		}

		pws = append(pws, w)

		// This following append method must not be moved before the closers above are appended
		// as the closer won't be able to close properly (flush order matters).
		// Thus, we put this line here and do not move it to other place.
		pcs = append(pcs, pw)
	}

	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
}", "oldString": "// Pipe readers, writer and closers for fanout the same writer.
