	assert.Equal(uint32(nonceSize+len(plaintext)+tagSize), chunkLen)

	nonce := stream[7 : 7+nonceSize]
	sealed := stream[7+nonceSize : 7+nonceSize+len(plaintext)+tagSize]

	// Sentinel: 4 zero bytes.
	sentinelStart := 7 + nonceSize + len(plaintext) + tagSize
	assert.Equal([]byte{0, 0, 0, 0}, stream[sentinelStart:sentinelStart+4])

	// Trailing 32-byte HMAC over the chunk bytes.
	hmacStart := sentinelStart + 4
	assert.Len(t, stream, hmacStart+hmacSize)

	mac := stream[hmacStart:]
	chunkBytes := stream[3:sentinelStart]

	// Independently verify the HMAC.
	macOK := hmacEqual(t, testKey, chunkBytes, mac)
	assert.True(t, macOK)

