func TestConfigValidate(t *testing.T) {
	assert := assert.New(t)

	validSalt := base64.StdEncoding.EncodeToString([]byte("salt-salt-salt-salt"))

	cases := []struct {
		name      string
		cfg       Config
		wantErr   bool
		errSubstr string
	}{
		{
			name:    "disabled is always valid",
			cfg:     Config{Enabled: false, KeySource: "bogus", KeyFile: "/x", Passphrase: "p"},
			wantErr: false,
		},
		{
			name:    "enabled with empty source",
			cfg:     Config{Enabled: true},
			wantErr: true,
		},
		{
			name:    "enabled with unsupported source",
			cfg:     Config{Enabled: true, KeySource: "magic"},
			wantErr: true,
		},
		{
			name:    "env source valid",
			cfg:     Config{Enabled: true, KeySource: "env", KeyEnvVar: "MY_KEY"},
			wantErr: false,
		},
		{
			name:    "env source case-insensitive",
			cfg:     Config{Enabled: true, KeySource: "ENV", KeyEnvVar: "MY_KEY"},
			wantErr: false,
		},
		{
			name:    "env source missing env var name",
			cfg:     Config{Enabled: true, KeySource: "env"},
			wantErr: true,
		},
		{
			name:      "env source rejects file field",
			cfg:       Config{Enabled: true, KeySource: "env", KeyEnvVar: "MY_KEY", KeyFile: "/key"},
			wantErr:   true,
			errSubstr: "mutually exclusive",
		},
		{
			name:      "file source rejects literal key field",
			cfg:       Config{Enabled: true, KeySource: "file", KeyFile: "/key", Key: "abc"},
			wantErr:   true,
			errSubstr: "mutually exclusive",
		},
		{
			name:    "file source valid",
			cfg:     Config{Enabled: true, KeySource: "file", KeyFile: "/key"},
			wantErr: false,
		},
		{
			name:    "file source missing path",
			cfg:     Config{Enabled: true, KeySource: "file"},
			wantErr: true,
		},
		{
			name:      "literal source rejects passphrase field",
			cfg:       Config{Enabled: true, KeySource: "literal", Key: "abc", Passphrase: "p"},
			wantErr:   true,
			errSubstr: "mutually exclusive",
		},
		{
			name:    "literal source valid",
			cfg:     Config{Enabled: true, KeySource: "literal", Key: "abc"},
			wantErr: false,
		},
		{
			name:    "literal source missing key",
			cfg:     Config{Enabled: true, KeySource: "literal"},
			wantErr: true,
		},
		{
			name:    "derive source valid",
			cfg:     Config{Enabled: true, KeySource: "derive", Passphrase: "p", Salt: validSalt},
			wantErr: false,
		},
		{
			name:    "derive source case-insensitive",
			cfg:     Config{Enabled: true, KeySource: "dErIvE", Passphrase: "p", Salt: validSalt},
			wantErr: false,
		},
		{
			name:    "derive source missing passphrase",
			cfg:     Config{Enabled: true, KeySource: "derive", Salt: validSalt},
			wantErr: true,
		},
		{
			name:    "derive source missing salt",
			cfg:     Config{Enabled: true, KeySource: "derive", Passphrase: "p"},
			wantErr: true,
		},
		{
			name:    "derive source short salt",
			cfg:     Config{Enabled: true, KeySource: "derive", Passphrase: "p", Salt: base64.StdEncoding.EncodeToString([]byte("short"))},
			wantErr: true,
		},
		{
			name:      "derive source rejects env var field",
			cfg:       Config{Enabled: true, KeySource: "derive", Passphrase: "p", Salt: validSalt, KeyEnvVar: "X"},
			wantErr:   true,
			errSubstr: "mutually exclusive",
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			err := tc.cfg.Validate()
			if tc.wantErr {
				assert.Error(err)
				if tc.errSubstr != "" {
					assert.Contains(err.Error(), tc.errSubstr)
				}
			} else {
				assert.NoError(err)
			}
		})
	}
}

