	require.NoError(t, err)

	cfg := Config{
		Enabled:    true,
		KeySource:  "derive",
		Passphrase: "hunter2",
		Salt:       base64.StdEncoding.EncodeToString(salt),
	}

	first, err := LoadKey(cfg)
	require.NoError(t, err)
	assert.Len(first, 32)

	// Deterministic: same passphrase and salt derive the same key.
	second, err := LoadKey(cfg)
	require.NoError(t, err)
	assert.Equal(first, second)

	// Different salt derives a different key.
	otherSalt := make([]byte, 16)
	_, err = rand.Read(otherSalt)
	require.NoError(t, err)

	other := cfg
	other.Salt = base64.StdEncoding.EncodeToString(otherSalt)
	derived, err := LoadKey(other)
	require.NoError(t, err)
	assert.NotEqual(first, derived)

	// Empty passphrase is rejected.
	empty := cfg
	empty.Passphrase = ""
	_, err = LoadKey(empty)
	assert.Error(t, err)

	// Short salt is rejected.
	shortSalt := cfg
	shortSalt.Salt = base64.StdEncoding.EncodeToString([]byte("tiny"))
	_, err = LoadKey(shortSalt)
	assert.Error(t, err)
}

