func TestJobValidateEncryption(t *testing.T) {
	assert := assert.New(t)

	job := NewJob("job1", "mysql", testDBDsn)
	err := job.Validate()
	assert.Nil(err)

	// Encryption enabled without a key source must fail validation.
	job.Encryption = encryption.Config{Enabled: true}
	err = job.Validate()
	assert.NotNil(err)

	// Unsupported key source must fail validation.
	job.Encryption = encryption.Config{Enabled: true, KeySource: "magic"}
	err = job.Validate()
	assert.NotNil(err)

	// Mutually exclusive fields must fail validation.
	job.Encryption = encryption.Config{Enabled: true, KeySource: "env", KeyEnvVar: "K", KeyFile: "/f"}
	err = job.Validate()
	assert.NotNil(err)
	assert.Contains(err.Error(), "mutually exclusive")

	// A valid encryption config passes.
	job.Encryption = encryption.Config{Enabled: true, KeySource: "env", KeyEnvVar: "K"}
	err = job.Validate()
	assert.Nil(err)

	// Invalid core fields still fail.
	badJob := NewJob("", "mysql", "")
	badJob.Encryption = encryption.Config{Enabled: true, KeySource: "env", KeyEnvVar: "K"}
	err = badJob.Validate()
	assert.ErrorIs(err, ErrMissingJobName)
