func EnsureFileSuffix(filename string, shouldGzip, shouldEncrypt bool) string {
	if !shouldGzip && !shouldEncrypt {
		return filename
	}

	// Work from the name without any encryption suffix so the .gz and .enc
	// suffixes are always emitted in the canonical order, keeping this
	// function idempotent.
	base := strings.TrimSuffix(filename, ".enc")
	wasEncrypted := base != filename

	if shouldGzip && !strings.HasSuffix(base, ".gz") {
		base += ".gz"
	}

	if shouldEncrypt || wasEncrypted {
		base += ".enc"
	}

	return base
